record.field:
today = datetime.date.today()
for r in self:
    state = 'unknown'
    if r.x_warranty_start and r.x_warranty_end:
        if today < r.x_warranty_start:
            state = 'future'
        elif today > r.x_warranty_end or (r.x_warranty_hours > 0 and r.x_hours >= r.x_warranty_hours):
            state = 'expired'
        else:
            state = 'active'
    r['x_warranty_status'] = state

today = datetime.date.today()
for r in self:
    r['x_due'] = bool(r.x_enabled and not r.x_machine_id.x_retired and ((r.x_next_date and r.x_next_date <= today) or (r.x_next_hours > 0 and r.x_machine_id.x_hours >= r.x_next_hours)))

for r in self:
    jobs = r.x_job_ids.filtered(lambda j: j.x_state not in ['done', 'cancel'])
    r['x_open_job_id'] = jobs[:1]
